package tools

import (
	"flag"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// updateCatalog rewrites the handover tool spec from the registry:
// go test ./internal/tools/ -run TestCatalogMatchesHandoverDoc -update
var updateCatalog = flag.Bool("update", false, "rewrite docs/handover/tools.md from the registry")

// catalogDoc is the handover tool spec (feature #22), generated by Catalog.
var catalogDoc = filepath.Join("..", "..", "docs", "handover", "tools.md")

// fullRegistry is the production registry with every optional tool on, so
// the handover doc lists everything the tool server can ever serve.
func fullRegistry(t *testing.T) *Registry {
	t.Helper()
	r, err := NewRegistry(time.Hour, WithPasswordReset(), WithMFAClear([]string{"U0000000"}, time.Hour))
	if err != nil {
		t.Fatalf("build the full registry: %v", err)
	}
	return r
}

// TestCatalogMatchesHandoverDoc keeps the tool and risk tier spec in sync
// with the code: any registry or refusal table change fails here until the
// doc is regenerated with -update.
func TestCatalogMatchesHandoverDoc(t *testing.T) {
	got := Catalog(fullRegistry(t))
	if *updateCatalog {
		if err := os.WriteFile(catalogDoc, []byte(got), 0o600); err != nil {
			t.Fatalf("write %s: %v", catalogDoc, err)
		}
		return
	}
	want, err := os.ReadFile(catalogDoc) //nolint:gosec // a fixed repo path, not input
	if err != nil {
		t.Fatalf("read %s: %v (run this test with -update to create it)", catalogDoc, err)
	}
	if string(want) != got {
		t.Fatalf("%s is out of date with the tool registry; run: go test ./internal/tools/ -run TestCatalogMatchesHandoverDoc -update", catalogDoc)
	}
}

func TestCatalogListsEveryToolOnce(t *testing.T) {
	r := fullRegistry(t)
	doc := Catalog(r)
	for _, tool := range r.Tools() {
		heading := "### `" + tool.Name + "`"
		if n := strings.Count(doc, heading); n != 1 {
			t.Errorf("tool %s: heading appears %d times, want 1", tool.Name, n)
		}
		if !strings.Contains(doc, "| `"+tool.Name+"` | "+string(tool.Tier)+" |") {
			t.Errorf("tool %s: summary row with tier %s missing", tool.Name, tool.Tier)
		}
	}
}

func TestCatalogNamesTheGuardsPerTool(t *testing.T) {
	doc := Catalog(fullRegistry(t))
	cases := []struct {
		tool, want string
	}{
		{ToolAccountUnlock, "kill switch, `TOOL_WRITE_LIMIT`"},
		{ToolPasswordResetLink, "kill switch, `TOOL_WRITE_LIMIT`"},
		{ToolTicketCreate, "`TICKET_CREATE_LIMIT`"},
		{ToolMFAClear, "IT approval in Slack"},
		{ToolGroupAccessRequest, "group owner approval in Slack"},
		{ToolPrivilegedAccessChange, "always refused"},
	}
	for _, c := range cases {
		row := catalogRow(t, doc, c.tool)
		if !strings.Contains(row, c.want) {
			t.Errorf("%s row %q does not name %q", c.tool, row, c.want)
		}
	}
	if row := catalogRow(t, doc, ToolEscalate); strings.Contains(row, "kill switch") {
		t.Errorf("escalate must never be behind the kill switch, row: %q", row)
	}
}

func TestCatalogListsEveryRefusal(t *testing.T) {
	doc := Catalog(fullRegistry(t))
	for _, r := range allRefusals {
		row := "| `" + string(r.code) + "` | " + string(r.outcome) + " | " + r.reason + " | " + r.sentence + " |"
		if !strings.Contains(doc, row) {
			t.Errorf("refusal row missing: %s", row)
		}
	}
}

func TestCatalogKeepsFreeTextOutOfTheAuditColumn(t *testing.T) {
	doc := Catalog(fullRegistry(t))
	// ticket_create's title is free text: listed as an argument, never as kept.
	if !strings.Contains(doc, "| `title` | yes | one line, 1 to 200 characters | no (free text) |") {
		t.Error("ticket_create title row missing or marked as kept in the audit log")
	}
}

// catalogRow returns the summary table row for one tool.
func catalogRow(t *testing.T, doc, name string) string {
	t.Helper()
	for _, line := range strings.Split(doc, "\n") {
		if strings.HasPrefix(line, "| `"+name+"` |") {
			return line
		}
	}
	t.Fatalf("no summary row for %s", name)
	return ""
}
